<?php
declare(strict_types=1);
require __DIR__.'/mon_reinforcement_fixture.php';
$cases=[];$dirs=[];$metrics=[];$start=mon_monotonic();
function rr_assert(bool $v,string $message='assertion'): void {if(!$v)throw new RuntimeException($message);}
function rr_fault(callable $fn,array $codes): void {try{$fn();}catch(MonFault $e){rr_assert(in_array($e->faultCode,$codes,true),'unexpected '.$e->faultCode);return;}throw new RuntimeException('expected fault');}
function rr_case(string $name,callable $fn): void {global $cases;MonExecution::$active=null;MonExecution::$store=null;MonPreparation::reset();
 try{$fn();$cases[]=['case'=>$name,'pass'=>true];}catch(Throwable $e){$cases[]=['case'=>$name,'pass'=>false,'error'=>$e->getMessage()];}}
function rr_dir(): string {global $dirs;$p=sys_get_temp_dir().'/mon-reinforcement-'.bin2hex(random_bytes(8));mkdir($p,0700);$dirs[]=$p;return $p;}
function rr_clean(string $dir): void {foreach(scandir($dir)as $f)if($f!=='.'&&$f!=='..'){if(is_dir($dir.'/'.$f))rr_clean($dir.'/'.$f);else unlink($dir.'/'.$f);}rmdir($dir);}
function rr_confirmation($d,$decision,string $variant='ready'): void {
 $now=$decision->fixed_as_of;$sid=$decision->selected[0]->symbol_id;$symbol=$d->watchlist->symbols[0];$s=$d->_test_snapshots->$sid;
 $plan=$s->entry_plans[1]??$s->entry_plans[0];$price=array_sum($plan->entry_zone)/2;
 $quoteAt=MonBudget::iso(MonRun::seconds($now)-($variant==='stale_price'?301:1));$riskAt=MonBudget::iso(MonRun::seconds($now)-($variant==='stale_trading'?301:1));
 $date=(new DateTimeImmutable($now))->setTimezone(new DateTimeZone('Asia/Seoul'))->format('Y-m-d');
 $decision->confirmations=(object)['new_evidence'=>[(object)['id'=>'proof','source_kind'=>'independent','source_url'=>'https://example.invalid/primary','claim'=>'Synthetic price, identity and corporate/trading review','checked_at'=>$now]],
  'changes'=>[(object)['symbol_id'=>$sid,'price_observation'=>(object)['symbol_id'=>$sid,'source_kind'=>'independent','currency'=>'KRW','venue'=>'KOSPI',
   'price'=>$variant==='outside_zone'?$price*2:$price,'quote_at'=>$quoteAt,'price_type'=>'last','timestamp_basis'=>'trade','delay_seconds'=>0,'session'=>'regular','market_date'=>$date,'evidence_ids'=>['proof']],
   'risk_review'=>(object)['status'=>$variant==='pending_risk'?'needs_check':'verified','trading_status'=>'verified','scope'=>'synthetic current company and trading check',
    'pending_items'=>$variant==='pending_risk'?['unconfirmed corporate event']:[],'applies_as_of'=>$now,'checked_at'=>$riskAt,'evidence_ids'=>['proof'],'confirmed_material_adverse'=>$variant==='adverse']]]];
}
function rr_artifact_and_job($d=null): array {
 $d=$d??reinforcement_fixture();$dir=rr_dir();$store=new MonStore($dir);$cfg=progress_test_config($dir);$c=reinforcement_context($d);$decision=reinforcement_decision($d,$c);$result=MonDetails::finalize($d,$decision);
 $budget=MonExecution::start($store,(object)['run_id'=>'job-'.bin2hex(random_bytes(5)),'received_at'=>mon_iso()]);
 $manifest=MonArtifact::create($store,MonRun::json($d),$result['files'],['run_context_id'=>$budget->run->run_context_id,'received_at'=>$budget->run->received_at,'decision_sha256'=>hash('sha256',MonRun::json($decision)),'prepared_fingerprint'=>$decision->prepared_fingerprint]);
 $git=new ReinforcementGit($d);$pub=new MonPublication($store,new MonHttp(null,[$git,'transport']),$cfg);$job=$pub->enqueue($manifest['artifact_id'],$git->head,$budget,'synthetic-operator');
 return [$d,$store,$cfg,$budget,$manifest,$git,$pub,$job,$result];
}
