rr_case('equivalent raw contexts have one normalized token',function(){
 $d=reinforcement_fixture();$a=reinforcement_context($d);$a->countries=['US','KR'];$a->rendered_at='2026-10-11T03:00:00Z';$sid=$d->watchlist->symbols[0]->symbol_id;$a->important_ids=[$sid,$sid];
 $b=clone $a;$b->countries=['KR','US'];$b->rendered_at='2026-10-11T12:00:00+09:00';$b->important_ids=[$sid];rr_assert(MonRun::token($d,$a)===MonRun::token($d,$b));});
