rr_case('run restart does not reset the original start',function(){
 $store=new MonStore(rr_dir());$now=microtime(true);$mono=0.;$wall=static function()use(&$now){return $now;};$clock=static function()use(&$mono){return $mono;};
 $r=(object)['run_id'=>'immutable','received_at'=>MonBudget::iso($now)];$b=MonExecution::start($store,$r,$wall,$clock);$original=$b->end('publication');$now+=65;$mono+=65;
 $again=MonExecution::start($store,$r,$wall,$clock);rr_assert($again->end('publication')===$original&&abs($again->remaining('publication')-55)<.01);
 rr_fault(static function()use($store,$now,$wall,$clock){MonExecution::start($store,(object)['run_id'=>'immutable','received_at'=>MonBudget::iso($now)],$wall,$clock);},['MON_RUN_START_IMMUTABLE']);});
rr_case('monotonic elapsed survives wall-clock rewind',function(){
 $store=new MonStore(rr_dir());$now=microtime(true);$mono=0.;$wall=static function()use(&$now){return $now;};$clock=static function()use(&$mono){return $mono;};
 $b=MonExecution::start($store,(object)['run_id'=>'rewind','received_at'=>MonBudget::iso($now)],$wall,$clock);$now-=100;$mono=17;rr_assert(abs($b->remaining('collection')-83)<.01);});
rr_case('normal phase budgets are absolute 100 110 120 300',function(){$store=new MonStore(rr_dir());$now=microtime(true);$wall=static function()use(&$now){return $now;};$b=MonExecution::start($store,(object)['run_id'=>'limits','received_at'=>MonBudget::iso($now)],$wall,static function(){return 0;});
 foreach(['collection'=>100,'decision'=>110,'publication'=>120,'recovery'=>300]as $k=>$v)rr_assert(abs($b->end($k)-MonRun::seconds($b->run->received_at)-$v)<.01);
 $now+=100;rr_fault(static function()use($b){$b->guard('collection');},['MON_COLLECTION_DEADLINE']);});
rr_case('extended recovery ends at original start plus 300',function(){$store=new MonStore(rr_dir());$r=(object)['run_id'=>'extended','received_at'=>mon_iso(),'mode'=>'extended','extension_reason'=>'synthetic missing benchmark'];$b=MonExecution::start($store,$r);rr_assert(abs($b->end('publication')-MonRun::seconds($b->run->received_at)-300)<.01);});
rr_case('missing receipt timestamp is explicitly partial',function(){$b=MonExecution::start(new MonStore(rr_dir()),(object)['run_id'=>'partial']);rr_assert($b->timing()['partial_timing']===true&&$b->run->timing_basis==='server_first_control');});
