 $http=new MonHttp(null,static function($method,$url,$headers,$body,$timeout)use(&$wall,&$mono,&$timeouts){$timeouts[]=$timeout;$wall-=30;$mono+=4;return ['status'=>200,'body'=>'{}','headers'=>[]];},$w,$m);
 $deadline=$wall+5;$http->rememberDeadline($deadline);$http->request('GET','https://api.github.com/test',[],null,$deadline,10);$http->request('GET','https://api.github.com/test',[],null,$deadline,10);
 rr_assert($timeouts[0]<=5&&$timeouts[1]<=1.00001&&$http->remaining($deadline)===0.0);rr_fault(static function()use($http,$deadline){$http->request('GET','https://api.github.com/test',[],null,$deadline);},['BUDGET_EXHAUSTED']);});
